target.css:
:root {
  --tag-bg: #fdf6e3;
  --tag-border: #7a5c3b;
  --tag-accent: #3b6e5c;
  --tag-muted: #9b7b55;
  --tag-text: #2c1f0f;
}

body {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 100vh;
  margin: 0;
}

.jar-tag {
  background: var(--tag-bg);
  border: 3px solid var(--tag-border);
  border-radius: 6px;
  width: 240px;
  padding: 16px 20px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  outline: 2px dashed var(--tag-muted);
  outline-offset: -7px;
}

.tag-header {
  display: flex;
  align-items: center;
  gap: 8px;
  border-bottom: 2px solid var(--tag-border);
  padding-bottom: 8px;
}

.tag-icon {
  font-size: 22px;
  line-height: 1;
}

.tag-title {
  margin: 0;
  font-size: 15px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--tag-accent);
}

.tag-body {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.specimen-name {
  margin: 0;
  font-size: 20px;
  font-weight: 700;
  color: var(--tag-text);
  line-height: 1.2;
}

.specimen-latin {
  margin: 0;
  font-size: 13px;
  font-style: italic;
  color: var(--tag-muted);
  line-height: 1.3;
}

.tag-footer {
  display: flex;
  justify-content: space-between;
  align-items: center;
  border-top: 1px solid var(--tag-muted);
  padding-top: 8px;
}

.tag-loc,
.tag-date {
  font-size: 11px;
  font-weight: 600;
  color: var(--tag-accent);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

